    "id": "test-receipt-001",
    "siteId": "site-001"
  },
  "template": {
    "body": "<root charset=\"utf-8\"><text align=\"center\" size=\"wide\">{{header}}</text><separator char=\"-\" /><text>Date: {{dateOfPrinting}}</text><text>Order: {{orders.docNumber}}</text><text>Total: {{orders.total}}</text><blank lines=\"1\" /><text>Thank you for your order!</text><blank lines=\"2\" /><command cmd=\"cut\" /></root>",
    "name": "Basic Receipt",
    "templateType": "Docket"
  },
  "templateData": "{\"printerDeviceName\":\"Microsoft Print to PDF\",\"header\":\"RECEIPT\",\"dateOfPrinting\":\"17/01/2025, 2:30 PM\",\"orders\":{\"docNumber\":\"005868\",\"total\":\"$25.50\"}}",
  "isOpenCashDrawer": false
}

{
  "_id": {
    "id": "test-products-001",
