  },
  "template": {
    "body": "<root charset=\"utf-8\"><text align=\"center\" size=\"wide\">{{header}}</text><separator char=\"-\" /><text>Date: {{dateOfPrinting}}</text><text>Order: {{orders.docNumber}}</text><docket-section /><separator char=\"-\" /><text>Total: {{orders.total}}</text><blank lines=\"2\" /><command cmd=\"cut\" /></root>",
