    "body": "<root charset=\"utf-8\"><text align=\"center\" size=\"wide\">CASH RECEIPT</text><separator char=\"-\" /><text>Date: {{dateOfPrinting}}</text><text>Order: {{orders.docNumber}}</text><text>Total: {{orders.total}}</text><text>Payment: CASH</text><blank lines=\"1\" /><text align=\"center\">Thank you!</text><blank lines=\"2\" /><command cmd=\"cut\" /></root>",
